import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const m=JSON.parse('{"title":"渙","description":"東坡易傳 - 渙","frontmatter":{"title":"渙","description":"東坡易傳 - 渙"},"headers":[],"relativePath":"classics/dongpo/060.md","filePath":"classics/dongpo/060.md"}'),o={name:"classics/dongpo/060.md"};function r(n,p,c,_,i,d){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="渙" tabindex="-1">渙 <a class="header-anchor" href="#渙" aria-label="Permalink to “渙”">​</a></h1><p>“渙”：亨，王假有廟，利涉大川，利貞。</p><p>《彖》曰：“渙，亨”，剛來而不窮，柔得位乎外而上同，“王假有廟”，王乃在中也；“利涉大川”，乘木有功也。</p><p>世之方治也，如大川安流而就下；及其亂也，潰溢四出而不可止。水非樂為此，蓋必有逆其性者，泛溢而不已。逆之者必哀，其性必復；水將自擇其所安而歸焉。古之善治者，未嘗與民爭；而聽其自擇，然後從而導之。“渙”之為言，天下流離渙散而不安其居，此宜經營四方之不暇。而其《彖》曰“王假有廟”；其《象》曰“先王以亨於帝立廟”，何也？曰：犯難而爭民者，民之所疾也；處危而不偷者，眾之所恃也。先王居渙散之中，安然不爭，而自為長久之計；宗廟既立，亨帝之位定，而天下之心始有所繫矣。“剛來而不窮者”，九二也；“柔得位乎外而上同”者，六四也。“渙”之得民，惟是二者，此所以“亨”也；然猶未免乎“渙”。“王假有廟”，謂五也；王至於有廟，而後可以涉大川，於是“渙”始有所歸矣。有所歸而後有川，有川而後可涉，“乘木”，乘舟也。舟之所行，川之所在也。</p><p>象曰：風行水上，“渙”；先王以享於帝立廟。</p><p>初六：用拯馬壯，吉。象曰：初六之“吉”，順也。</p><p>九二在險中，得初六而安，故曰：“用拯馬壯，吉。”“明夷”之六二，有馬不以自乘，而以拯上六之傷；“渙”之初六，有馬不以自乘，而以拯九二之險。故《象》皆以為“順”，言其忠順之至也。</p><p>九二：渙奔其機，悔亡。象曰：“渙奔其機”，得原也。</p><p>得初六而安，是謂“機”也①。</p><p>【校注】 ① 機：《蘇氏易傳》均作“杌”，誤。</p><p>六三：渙其躬，無悔。象曰：“渙其躬”，志在外也。</p><p>渙之世，民無常主。六三有應於上，志在外者也；而近於九二，二者必爭焉，故“渙其躬”，無所適從，惟有道者是予而後安。</p><p>六四：渙其群，元吉；渙有丘，匪夷所思。象曰：“渙其群，元吉”，光大也。</p><p>上九之有六三者，以應也；九五之有六四、九二之有初六者，以近也；皆有以群之。“渙”而至於群，天下始有可收之漸。其德大者，其所群也大；其德小者，其所群也小。小者合於大，大者合於一，是謂“渙其群”也。近五而得位，則四之所群者最大也，因君以得民，有民以自封殖，是謂“丘”也；“夷”、平也，民之蕩蕩焉，未有所適從者也。彼方不知其所從，而我則為丘以聚之，豈“夷”者之所思哉？民之所思，思夫有德而爭民者也。</p><p>九五：渙汗，其大號；渙，王居無咎。象曰：“王居無咎”，正位也。</p><p>“汗”，取其周浹而不反也。宗廟既立，亨帝之位定，而“大號”令出焉。其曰“渙，王居”，何也？《彖》曰：“王假有廟，王乃在中也。”渙然之中，不知其孰為臣、孰為主①；至於有廟，而天下始知王之所在矣，故曰“渙，王居”，言“渙”之中有王居矣。</p><p>【校注】 ①孰為臣、孰為主：《蘇氏易傳》作“孰為主、孰為臣。”</p><p>上九：渙其血，去逖出，無咎。象曰：“渙其血”，遠害也。</p><p>上九求六三，必與九二爭而傷焉；“渙其血”，不爭也；九二“剛來而不窮”，不可與爭者也。雖不爭而處爭之地，猶未免也，故去而遠出，然後無咎。</p>',19)])])}const f=a(o,[["render",r]]);export{m as __pageData,f as default};
